const OWNER_API='https://fpgtwgtoqtokpitzlbie.supabase.co/functions/v1/akiya-pocket-owner';
const ENTRY_COOKIE='akiya_owner_entry';
const SESSION_COOKIE='akiya_owner_session';
const enc=new TextEncoder();
function htmlHeaders(){return {'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex, nofollow, noarchive, nosnippet','x-content-type-options':'nosniff','referrer-policy':'no-referrer','content-security-policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'"}}
function jsonHeaders(){return {'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex, nofollow, noarchive, nosnippet','x-content-type-options':'nosniff'}}
function parseCookies(req){const out={};for(const part of (req.headers.get('cookie')||'').split(';')){const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())}return out}
function same(a,b){const x=enc.encode(String(a||'')),y=enc.encode(String(b||''));if(x.length!==y.length)return false;let d=0;for(let i=0;i<x.length;i++)d|=x[i]^y[i];return d===0}
function notFound(){return new Response('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Not Found</title><body><h1>404</h1></body></html>',{status:404,headers:htmlHeaders()})}
function loginHtml(){return `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive,nosnippet"><title>空家ポケット 運営センター</title><style>*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP",sans-serif;background:#f4f7fb;color:#172033}.w{max-width:1180px;margin:auto;padding:18px}.c{background:#fff;border:1px solid #dfe6ef;border-radius:16px;padding:16px;margin-bottom:14px}.t{font-size:21px;font-weight:800;color:#082b58}.s{font-size:12px;color:#65758b}.g{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.n{font-size:26px;font-weight:850;color:#082b58}.l{font-size:12px;color:#69788c}.b{border:1px solid #cbd5e1;border-radius:10px;padding:10px 13px;background:#fff;font-weight:700;cursor:pointer}.p{background:#082b58;color:#fff;border-color:#082b58}.ok{background:#ecfdf3;color:#0c7a43}.no{background:#fff1f0;color:#b42318}.a{display:flex;flex-wrap:wrap;gap:8px}.f{margin:10px 0}.f label{display:block;font-size:13px;font-weight:700;margin-bottom:5px}.f input,.f textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.tbl{width:100%;border-collapse:collapse;font-size:13px}.tbl th,.tbl td{padding:9px 7px;border-bottom:1px solid #eef2f6;text-align:left}.cols{display:grid;grid-template-columns:1.35fr .65fr;gap:14px}.chip{display:inline-block;padding:6px 9px;border-radius:999px;background:#eef2f6;font-size:12px;font-weight:700;margin:3px}.notice{padding:10px;border-radius:9px;background:#fff7ed;color:#9a3412;font-size:13px}@media(max-width:900px){.g{grid-template-columns:repeat(3,1fr)}.cols{grid-template-columns:1fr}}@media(max-width:560px){.g{grid-template-columns:repeat(2,1fr)}}</style></head><body><main id="app"></main><script>const app=document.getElementById('app'),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),yen=n=>'¥'+Number(n||0).toLocaleString('ja-JP');async function call(action,data={}){const r=await fetch('/api/owner',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({action,...data})});let x={};try{x=await r.json()}catch{}if(r.status===401&&action!=='login')login();return x}function login(){app.innerHTML='<div class="w" style="max-width:430px;padding-top:8vh"><div class="c"><div class="t">空家ポケット 運営センター</div><div class="s">本人専用。ログイン前は会員・依頼・売上データを表示しません。</div><div class="f"><label>管理者メール</label><input id="email" autocomplete="username"></div><div class="f"><label>管理パスワード</label><input id="pass" type="password" autocomplete="current-password"></div><button class="b p" id="go">ログイン</button><div class="s" id="st" style="margin-top:9px"></div></div></div>';go.onclick=async()=>{st.textContent='確認中…';const x=await call('login',{email:email.value,password:pass.value});if(!x.ok){st.textContent='ログインできません。';return}render()}}async function render(){const x=await call('dashboard');if(!x.ok)return;const d=x.data,s=d.settings||{};app.innerHTML='<div class="w"><div class="c"><div style="display:flex;justify-content:space-between;align-items:center"><div><div class="t">空家ポケット 運営センター</div><div class="s">管理画面＋完全自動化</div></div><div class="a"><button class="b" id="refresh">更新</button><button class="b" id="logout">ログアウト</button></div></div></div><div class="g">'+[['実会員',d.members],['依頼',d.requests],['支払済み',d.paid],['あなたがやる案件',d.work],['売上',yen(d.revenue)],['7日間行動データ',d.events]].map(v=>'<div class="c"><div class="l">'+v[0]+'</div><div class="n">'+v[1]+'</div></div>').join('')+'</div><div class="cols"><div class="c"><div class="t" style="font-size:17px">あなたがやる案件</div><div style="overflow:auto"><table class="tbl"><thead><tr><th>案件</th><th>物件</th><th>状態</th><th>決済</th><th>訪問日</th><th>金額</th></tr></thead><tbody>'+((d.recentRequests||[]).map(r=>'<tr><td>'+esc(r.request_id)+'</td><td>'+esc(r.property_address)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.payment_status)+'</td><td>'+esc(r.visit_date||'—')+'</td><td>'+yen(r.quoted_total)+'</td></tr>').join('')||'<tr><td colspan="6">まだ依頼はありません。</td></tr>')+'</tbody></table></div></div><div class="c"><div class="t" style="font-size:17px">完全自動化</div><div><span class="chip '+(s.full_auto_enabled?'ok':'no')+'">完全自動 '+(s.full_auto_enabled?'ON':'OFF')+'</span><span class="chip '+(s.growth_enabled?'ok':'no')+'">集客 '+(s.growth_enabled?'ON':'OFF')+'</span><span class="chip '+(s.health_monitor_enabled?'ok':'no')+'">障害監視 '+(s.health_monitor_enabled?'ON':'OFF')+'</span><span class="chip no">メール 強制OFF</span></div><div class="a" style="margin-top:10px"><button class="b ok" id="on">完全自動 ON</button><button class="b no" id="off">完全自動 OFF</button><button class="b" id="metrics">今すぐ集計</button><button class="b" id="diag">障害診断</button></div><div class="s" id="diagout"></div></div></div><div class="cols"><div class="c"><div class="t" style="font-size:17px">集客データ</div>'+Object.entries(d.sources||{}).sort((a,b)=>b[1]-a[1]).map(([k,v])=>'<div>'+esc(k)+'：'+v+'</div>').join('')+'</div><div class="c"><div class="t" style="font-size:17px">最近の会員</div><table class="tbl"><tbody>'+((d.recentMembers||[]).map(m=>'<tr><td>'+esc(m.name)+'<br><span class="s">'+esc(m.member_no)+'</span></td><td>'+esc((m.property_prefecture||'')+' '+(m.property_city||''))+'</td></tr>').join('')||'<tr><td>まだ実会員はいません。</td></tr>')+'</tbody></table></div></div><div class="c"><div class="t" style="font-size:17px">現地確認後の報告</div><div class="cols"><div><div class="f"><label>案件ID</label><input id="req"></div><div class="f"><label>写真枚数</label><input id="photos" type="number" min="0" value="0"></div></div><div><div class="f"><label>報告メモ</label><textarea id="summary" rows="3"></textarea></div><div class="f"><label>報告URL（任意）</label><input id="url"></div></div></div><button class="b p" id="complete">報告完了</button><span class="s" id="reportout"></span></div></div>';refresh.onclick=render;logout.onclick=async()=>{await call('logout');login()};on.onclick=async()=>{await call('set_auto',{enabled:true});render()};off.onclick=async()=>{await call('set_auto',{enabled:false});render()};metrics.onclick=async()=>{await call('refresh_metrics');render()};diag.onclick=async()=>{const y=await call('diagnostic');diagout.textContent=y.ok?y.checks.map(c=>c.label+':'+(c.ok?'正常':'異常')+'('+c.status+')').join(' / '):'診断失敗'};complete.onclick=async()=>{const y=await call('complete_report',{requestId:req.value,summary:summary.value,photoCount:photos.value,reportUrl:url.value});reportout.textContent=y.ok?'報告完了にしました。':'完了できませんでした。';if(y.ok)render()}}login();</script></body></html>`}
async function proxy(req,env){const c=parseCookies(req);if(!same(c[ENTRY_COOKIE],env.ENTRY_KEY))return notFound();if(req.method!=='POST')return new Response(JSON.stringify({ok:false}),{status:405,headers:jsonHeaders()});let b={};try{b=await req.json()}catch{}const action=String(b.action||''),token=c[SESSION_COOKIE]||'';const payload={...b,uiKey:env.OWNER_UI_KEY,token};const r=await fetch(OWNER_API,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});let x={};try{x=await r.json()}catch{x={ok:false,code:'UPSTREAM_INVALID'}}const h=jsonHeaders();if(action==='login'&&r.ok&&x.ok&&x.token){h['set-cookie']=SESSION_COOKIE+'='+encodeURIComponent(x.token)+'; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=43200';delete x.token}else if(action==='logout'){h['set-cookie']=SESSION_COOKIE+'=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0'}return new Response(JSON.stringify(x),{status:r.status,headers:h})}
export default {async fetch(req,env){const u=new URL(req.url),c=parseCookies(req);if(u.pathname==='/enter'&&req.method==='GET'){const k=u.searchParams.get('key')||'';if(!same(k,env.ENTRY_KEY))return notFound();return new Response(null,{status:302,headers:{location:'/owner','cache-control':'no-store','set-cookie':ENTRY_COOKIE+'='+encodeURIComponent(env.ENTRY_KEY)+'; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=31536000','x-robots-tag':'noindex, nofollow'}})}if(u.pathname==='/owner'&&req.method==='GET'){if(!same(c[ENTRY_COOKIE],env.ENTRY_KEY))return notFound();return new Response(loginHtml(),{status:200,headers:htmlHeaders()})}if(u.pathname==='/api/owner')return proxy(req,env);return notFound()}};
